<?php
namespace App\Http\Controllers;
use App\Models\Activity;use App\Models\User;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\View\View;
class PhoneCallController extends Controller{public function index(Request $r):View{$f=$r->validate(['channel'=>['nullable','in:phone,email'],'status'=>['nullable','in:verified,not_verified'],'user'=>['nullable','integer'],'from'=>['nullable','date'],'to'=>['nullable','date']]);$types=isset($f['channel'])?[ucfirst($f['channel'])]:['Phone','Email'];$calls=Activity::query()->with(['type','user'])->whereHas('type',fn($q)=>$q->whereIn('name',$types))->when($f['user']??null,fn($q,$v)=>$q->where('user_id',$v))->when(($f['status']??'')==='verified',fn($q)=>$q->whereNotNull('verified_at'))->when(($f['status']??'')==='not_verified',fn($q)=>$q->whereNull('verified_at'))->when($f['from']??null,fn($q,$v)=>$q->whereDate('from_at','>=',$v))->when($f['to']??null,fn($q,$v)=>$q->whereDate('from_at','<=',$v))->latest('from_at')->get();return view('phone-calls.index',['calls'=>$calls,'filters'=>$f,'users'=>User::where('is_active',true)->orderBy('name')->get()]);}public function verify(Activity $activity):RedirectResponse{$activity->update(['verified_at'=>now()]);return back()->with('success','Phone call verified.');}}
